package com.eventplatform.attendee.application;
import com.eventplatform.attendee.domain.*; import java.time.Clock; import java.util.List; import org.springframework.data.domain.PageRequest; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class BookingSagaRecoveryJob {private final BookingSagaRepository repository;private final BookingSagaService service;private final Clock clock;public BookingSagaRecoveryJob(BookingSagaRepository repository,BookingSagaService service,Clock clock){this.repository=repository;this.service=service;this.clock=clock;}@Scheduled(fixedDelayString="${platform.booking-saga.recovery-interval:5s}")public void recover(){repository.findDue(List.of(BookingSagaState.INVENTORY_CONFIRMATION_PENDING,BookingSagaState.COMPENSATION_PENDING),clock.instant(),PageRequest.of(0,50)).forEach(service::recover);}}
